#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

ENV_FILE="$HOME/.trendi-vps/secrets.env"
mkdir -p "$(dirname "$ENV_FILE")" && chmod 700 "$(dirname "$ENV_FILE")"

TOTAL_STAGES=6

banner "Buy the Concierge phone number (Telnyx DID)"

note "This is the one paid, human-only step left for a customer-dialable number."
note "Everything after it - Asterisk, the Grok bridge, CRM capture, owner SMS/email -"
note "is already built and tested; the number is the missing ingress."
pause "Ready?"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Know what you are buying"
say "A number in the country your customers call from, on the existing Telnyx connection."
step "Telnyx SIP/Number pricing: per-number per-month plus per-minute; pay-as-you-go."
step "New Zealand numbers require address/KYC review by Telnyx before activation."
step "Your account needs a payment method before any number is provisioned."
warn "Do not buy from resellers advertising 'instant DID' - that is where the earlier scam attempts led."
if ! confirm "Account has a payment method and (for NZ) KYC documents ready?"; then
  say "Open https://portal.telnyx.com/#/app/billing and https://portal.telnyx.com/#/app/account/kyc first."
  pause "Enter to exit and re-run when ready."
  return 1
fi
pause

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Buy the number"
open_url "https://portal.telnyx.com/#/app/numbers/buy"
say "If the dashboard layout differs, the page is Numbers -> Buy numbers."
step "Country: New Zealand (or the customer's country)."
step "Features: Voice. Capabilities: inbound and outbound."
step "Search, pick a local number, complete the cart, confirm the monthly charge."
step "Wait for the number to show Active in Numbers -> My numbers."
say ""
note "Numbers bought in an NZ DID block activate in minutes; KYC review can take a day."
ask DID_E164 "Paste the number in E.164 (e.g. +6491234567):"
if [[ ! "$DID_E164" =~ ^\+[1-9][0-9]{7,14}$ ]]; then
  warn "that is not an E.164 number (+ and digits only)"
  pause "Enter to exit; re-run with the correct number."
  return 1
fi
write_env DID_E164 "$DID_E164"
pause

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Route the number to the Asterisk box"
say "The Telnyx connection named Trendi is an IP connection to the Asterisk host."
open_url "https://portal.telnyx.com/#/app/numbers/my-numbers"
step "Open the number, Connection tab."
step "Assign it to the existing connection: Trendi (do not create a second one)."
step "Confirm inbound is enabled and the connection still shows the Asterisk public IP."
step "If Telnyx asks for a SIP URI instead of an IP connection, use the value already on"
step "the Trendi connection - do not type a new host."
say ""
warn "A wrong connection here means calls ring nowhere; the owner cannot fix it later."
if ! confirm "Number assigned to the Trendi connection and Active?"; then
  pause "Fix the routing in the portal, then re-run this wizard. Enter to exit."
  return 1
fi
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Register the number for this business"
say "The Asterisk dialplan matches the exact DID; the app needs the number row and the"
say "tenant switch before a call can be answered for a business."
ask VPS_HOST "SSH host for the Concierge VPS (ssh alias or user@host):"
ask TENANT_SLUG "Business slug (e.g. pukeko-construction):"
if ! ssh -o BatchMode=yes -o ConnectTimeout=8 "$VPS_HOST" 'test -f /opt/trendi/shared/api.env' 2>/dev/null; then
  warn "cannot reach the VPS over ssh to $VPS_HOST"
  pause "Fix SSH, then re-run. Enter to exit."
  return 1
fi
say ""
say "Running these admin calls on the box (admin token read from api.env, never printed):"
step "POST /admin/tenants/$TENANT_SLUG/phone-numbers {\"e164\":\"$DID_E164\"}"
step "PATCH /admin/tenants/$TENANT_SLUG/phone-numbers/$DID_E164 {\"enabled\":true}"
step "PATCH /admin/tenants/$TENANT_SLUG {\"phone_enabled\":true}"
if confirm "Run them now?"; then
  ssh "$VPS_HOST" "set -a; . /opt/trendi/shared/api.env; set +a; \
    base=http://127.0.0.1:8000; auth=\"Authorization: Bearer \$ADMIN_TOKEN\"; \
    curl -fsS -X POST -H \"\$auth\" -H 'content-type: application/json' \
      -d '{\"e164\":\"$DID_E164\"}' \$base/admin/tenants/$TENANT_SLUG/phone-numbers && echo && \
    curl -fsS -X PATCH -H \"\$auth\" -H 'content-type: application/json' \
      -d '{\"enabled\":true}' \$base/admin/tenants/$TENANT_SLUG/phone-numbers/$DID_E164 && echo && \
    curl -fsS -X PATCH -H \"\$auth\" -H 'content-type: application/json' \
      -d '{\"phone_enabled\":true}' \$base/admin/tenants/$TENANT_SLUG && echo" || {
    warn "an admin call failed - read the JSON above; a 409 means the number is already registered"
    pause "Enter to continue anyway."
  }
else
  SKIPPED+=("register $DID_E164 for $TENANT_SLUG via the admin API")
fi
pause

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Call it from a real phone"
say "Use a phone that is NOT on the VPS network so the call comes in over the carrier."
step "Dial $DID_E164 and let the Grok receptionist answer."
step "Say a test enquiry (e.g. 'I need a quote for cladding a 40 square metre wall')."
step "Accept the confirmation by email or text when asked."
step "End the call."
say ""
note "Expected within a minute: a phone_calls row, a CRM lead with the transcript, and an"
note "owner SMS + email. The owner alert also carries the recording link once consent was given."
ask CALL_OK "Did the receptionist answer and did the owner alert arrive? (yes/no):"
if [[ "$CALL_OK" =~ ^[Yy] ]]; then
  note "Phone path is live."
else
  warn "Capture the Asterisk log: ssh $VPS_HOST 'docker logs --tail 200 trendi-asterisk 2>&1 | tail -50'"
  SKIPPED+=("verify the first inbound call on $DID_E164")
fi
pause

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Tell the customer what to forward"
say "The number is dialable, but the owner's own phone keeps ringing until their carrier"
say "forwards unanswered/busy calls to it."
step "Give the owner the star-code instructions for their carrier (busy + no answer)."
step "Destination: $DID_E164."
step "Owner delivery number/email is set in the portal Setup tab - confirm it is current."
note "Forwarding is the customer's carrier setting; we cannot set it for them."

finish
note "DID: $DID_E164 (tenant $TENANT_SLUG) - stored at $ENV_FILE (0600)."
note "Next: the owner completes carrier forwarding; then the number is customer-dialable."
}

run_wizard "$@"; exit
